window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5a474c54891f05e8"]={"versions": [{"id": "FIG-5a474c54891f05e8", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsmatrix für das End-to-End-Schutzprofil E2E Profile 2 (E2E Library) in der AUTOSAR-Sicherheitskommunikation. Das Schaubild veranschaulicht die senderindividuelle Zuordnung von Datenbezeichnern (<code>DataIDList</code>) in Abhängigkeit vom 4-Bit-Nachrichtenzähler (<code>Counter</code>, Wertebereich 0 bis 15) bei 1:n- und N:1-Kommunikationsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-ECU / message</strong>: Zeilenbezeichner für sechs beispielhafte Sender-Steuergeräte (<code>Sender A</code>, <code>Sender B</code>, <code>Sender C</code>, <code>Sender D</code>, <code>Sender E</code>, <code>Sender F</code>).</li>\n<li><strong>DataIDList</strong>: 16-elementiges Array pro Sender mit Spalten für <code>DataID for Counter = 0</code> bis <code>15</code>.</li>\n<li><strong>Wertebereich / Datentyp</strong>: 8-Bit-Ganzzahlen (0–255), die als sender- und zählerspezifische Daten-IDs fungieren (z. B. Sender A: 177, 103, 29, ...).</li>\n<li><strong>Kollision / Hervorhebung</strong>: Bei Counter = 6 teilen sich Sender B und Sender E denselben Wert <code>18</code> (fett hervorgehoben), um die Handhabung partieller ID-Überschneidungen zu demonstrieren.</li>\n<li><strong>Sonderfall</strong>: Zeile <code>Sender F</code> führt für alle Zählerwerte identisch den Wert <code>244</code> („←special case of static DataID“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei jeder Übertragung inkrementiert die Sender-ECU den zyklischen 4-Bit-Zähler modulo 16 (<code>Counter</code> 0..15). Vor der CRC-Berechnung wählt die E2E-Bibliothek aus dem Array <code>DataIDList</code> den zum aktuellen Zählerstand korrespondierenden 8-Bit-Wert aus. Der Empfänger prüft anhand seiner lokal konfigurierten <code>DataIDList</code> die Übereinstimmung der empfangenen Prüfsumme. Der Spezialfall mit statischer DataID (Sender F) bildet ein Profil mit über alle Zyklen konstanter DataID ab, während dynamische Listen (Sender A bis E) zusätzlichen Schutz gegen Falscheinspeisung durch Wiederholungs- oder Verwechslungsfehler bieten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix definiert die Vorgaben für die Konfiguration des E2E Profile 2. Wesentliche Implementierungshinweise:</p>\n<ul class=\"fig-list\">\n<li>Bei Kommunikationsbeziehungen mit mehreren Sendern (1:n bzw. N:1) müssen die <code>DataIDList</code>-Arrays der verschiedenen Sender so gewählt werden, dass eine eindeutige Unterscheidbarkeit über mehrere aufeinanderfolgende Zählerstände gewährleistet bleibt.</li>\n<li>Eine punktuelle Identität eines Einzelwerts bei gleichem Zählerstand (im Diagramm: Wert <code>18</code> bei Sender B und E bei Zähler 6) ist zulässig, sofern die Gesamtsequenzen orthogonal bzw. über mehrere Nachrichtenzyklen hinweg eindeutig unterscheidbar bleiben.</li>\n<li>Für die statische Zuordnung (Sender F) müssen alle 16 Feldelemente auf denselben Wert initialisiert werden.</li>\n</ul>"}, {"id": "FIG-ec939779f10cbf97", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsmatrix für das End-to-End-Schutzprofil E2E Profile 2 (E2E Library) in der AUTOSAR-Sicherheitskommunikation. Das Schaubild veranschaulicht die senderindividuelle Zuordnung von Datenbezeichnern (<code>DataIDList</code>) in Abhängigkeit vom 4-Bit-Nachrichtenzähler (<code>Counter</code>, Wertebereich 0 bis 15) bei 1:n- und N:1-Kommunikationsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-ECU / message</strong>: Zeilenbezeichner für sechs beispielhafte Sender-Steuergeräte (<code>Sender A</code>, <code>Sender B</code>, <code>Sender C</code>, <code>Sender D</code>, <code>Sender E</code>, <code>Sender F</code>).</li>\n<li><strong>DataIDList</strong>: 16-elementiges Array pro Sender mit Spalten für <code>DataID for Counter = 0</code> bis <code>15</code>.</li>\n<li><strong>Wertebereich / Datentyp</strong>: 8-Bit-Ganzzahlen (0–255), die als sender- und zählerspezifische Daten-IDs fungieren (z. B. Sender A: 177, 103, 29, ...).</li>\n<li><strong>Kollision / Hervorhebung</strong>: Bei Counter = 6 teilen sich Sender B und Sender E denselben Wert <code>18</code> (fett hervorgehoben), um die Handhabung partieller ID-Überschneidungen zu demonstrieren.</li>\n<li><strong>Sonderfall</strong>: Zeile <code>Sender F</code> führt für alle Zählerwerte identisch den Wert <code>244</code> („←special case of static DataID“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei jeder Übertragung inkrementiert die Sender-ECU den zyklischen 4-Bit-Zähler modulo 16 (<code>Counter</code> 0..15). Vor der CRC-Berechnung wählt die E2E-Bibliothek aus dem Array <code>DataIDList</code> den zum aktuellen Zählerstand korrespondierenden 8-Bit-Wert aus. Der Empfänger prüft anhand seiner lokal konfigurierten <code>DataIDList</code> die Übereinstimmung der empfangenen Prüfsumme. Der Spezialfall mit statischer DataID (Sender F) bildet ein Profil mit über alle Zyklen konstanter DataID ab, während dynamische Listen (Sender A bis E) zusätzlichen Schutz gegen Falscheinspeisung durch Wiederholungs- oder Verwechslungsfehler bieten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix definiert die Vorgaben für die Konfiguration des E2E Profile 2. Wesentliche Implementierungshinweise:</p>\n<ul class=\"fig-list\">\n<li>Bei Kommunikationsbeziehungen mit mehreren Sendern (1:n bzw. N:1) müssen die <code>DataIDList</code>-Arrays der verschiedenen Sender so gewählt werden, dass eine eindeutige Unterscheidbarkeit über mehrere aufeinanderfolgende Zählerstände gewährleistet bleibt.</li>\n<li>Eine punktuelle Identität eines Einzelwerts bei gleichem Zählerstand (im Diagramm: Wert <code>18</code> bei Sender B und E bei Zähler 6) ist zulässig, sofern die Gesamtsequenzen orthogonal bzw. über mehrere Nachrichtenzyklen hinweg eindeutig unterscheidbar bleiben.</li>\n<li>Für die statische Zuordnung (Sender F) müssen alle 16 Feldelemente auf denselben Wert initialisiert werden.</li>\n</ul>"}, {"id": "FIG-3cf252327f233caf", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarische Konfigurationsmatrix für das End-to-End-Schutzprofil E2E Profile 2 (E2E Library) in der AUTOSAR-Sicherheitskommunikation. Das Schaubild veranschaulicht die senderindividuelle Zuordnung von Datenbezeichnern (<code>DataIDList</code>) in Abhängigkeit vom 4-Bit-Nachrichtenzähler (<code>Counter</code>, Wertebereich 0 bis 15) bei 1:n- und N:1-Kommunikationsbeziehungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die tabellarische Struktur gliedert sich in folgende Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Sender-ECU / message</strong>: Zeilenbezeichner für sechs beispielhafte Sender-Steuergeräte (<code>Sender A</code>, <code>Sender B</code>, <code>Sender C</code>, <code>Sender D</code>, <code>Sender E</code>, <code>Sender F</code>).</li>\n<li><strong>DataIDList</strong>: 16-elementiges Array pro Sender mit Spalten für <code>DataID for Counter = 0</code> bis <code>15</code>.</li>\n<li><strong>Wertebereich / Datentyp</strong>: 8-Bit-Ganzzahlen (0–255), die als sender- und zählerspezifische Daten-IDs fungieren (z. B. Sender A: 177, 103, 29, ...).</li>\n<li><strong>Kollision / Hervorhebung</strong>: Bei Counter = 6 teilen sich Sender B und Sender E denselben Wert <code>18</code> (fett hervorgehoben), um die Handhabung partieller ID-Überschneidungen zu demonstrieren.</li>\n<li><strong>Sonderfall</strong>: Zeile <code>Sender F</code> führt für alle Zählerwerte identisch den Wert <code>244</code> („←special case of static DataID“).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei jeder Übertragung inkrementiert die Sender-ECU den zyklischen 4-Bit-Zähler modulo 16 (<code>Counter</code> 0..15). Vor der CRC-Berechnung wählt die E2E-Bibliothek aus dem Array <code>DataIDList</code> den zum aktuellen Zählerstand korrespondierenden 8-Bit-Wert aus. Der Empfänger prüft anhand seiner lokal konfigurierten <code>DataIDList</code> die Übereinstimmung der empfangenen Prüfsumme. Der Spezialfall mit statischer DataID (Sender F) bildet ein Profil mit über alle Zyklen konstanter DataID ab, während dynamische Listen (Sender A bis E) zusätzlichen Schutz gegen Falscheinspeisung durch Wiederholungs- oder Verwechslungsfehler bieten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix definiert die Vorgaben für die Konfiguration des E2E Profile 2. Wesentliche Implementierungshinweise:</p>\n<ul class=\"fig-list\">\n<li>Bei Kommunikationsbeziehungen mit mehreren Sendern (1:n bzw. N:1) müssen die <code>DataIDList</code>-Arrays der verschiedenen Sender so gewählt werden, dass eine eindeutige Unterscheidbarkeit über mehrere aufeinanderfolgende Zählerstände gewährleistet bleibt.</li>\n<li>Eine punktuelle Identität eines Einzelwerts bei gleichem Zählerstand (im Diagramm: Wert <code>18</code> bei Sender B und E bei Zähler 6) ist zulässig, sofern die Gesamtsequenzen orthogonal bzw. über mehrere Nachrichtenzyklen hinweg eindeutig unterscheidbar bleiben.</li>\n<li>Für die statische Zuordnung (Sender F) müssen alle 16 Feldelemente auf denselben Wert initialisiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-5a474c54891f05e8", "to": "FIG-ec939779f10cbf97", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-ec939779f10cbf97", "to": "FIG-5a474c54891f05e8", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-5a474c54891f05e8", "to": "FIG-3cf252327f233caf", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
